<?php
defined('ABSPATH') || exit;
require MKT_DIR . 'templates/_header.php';
$public_id=(string)get_query_var('mkt_object_id');
$listing=MKT_Listings::get($public_id,false);
$recall=class_exists('MKT_Governance') ? MKT_Governance::public_recall($public_id) : null;
// A recall activation intentionally pauses an active listing. Keep a narrowly
// scoped public safety notice reachable for that exact recalled object without
// re-exposing arbitrary drafts/paused/private listings.
if (!$listing && $recall) $listing=MKT_Listings::get($public_id,true);
if (!$listing) { status_header(404); ?>
<section class="mkt-empty"><span aria-hidden="true">!</span><h1><?php esc_html_e('Listing unavailable','marketplace'); ?></h1><p><?php esc_html_e('The listing may have expired, been removed, or no longer be publicly eligible.','marketplace'); ?></p><a class="mkt-button mkt-button-primary" href="<?php echo esc_url(home_url('/marketplace/')); ?>"><?php esc_html_e('Return to Marketplace','marketplace'); ?></a></section>
<?php require MKT_DIR.'templates/_footer.php'; return; }
$item=MKT_Listings::public_dto($listing);
$language=MKT_Finalization::listing_language((int)$listing['id']);
$evidence=class_exists('MKT_Governance') ? MKT_Governance::public_evidence((string)$item['public_id']) : null;
?>
<article class="mkt-listing-detail" data-listing-id="<?php echo esc_attr($item['public_id']); ?>">
  <div class="mkt-gallery" aria-label="<?php esc_attr_e('Listing media','marketplace'); ?>"><?php if (!$item['media']): ?><div class="mkt-gallery-empty" aria-hidden="true">▧</div><?php endif; ?><?php foreach ($item['media'] as $media): $url=$media['metadata']['url'] ?? $media['metadata']['thumbnail_url'] ?? ''; if (!$url) continue; ?><figure><img src="<?php echo esc_url((string)$url); ?>" alt="<?php echo esc_attr((string)$media['alt_text']); ?>" loading="lazy"></figure><?php endforeach; ?></div>
  <div class="mkt-detail-panel">
    <p class="mkt-eyebrow"><?php echo esc_html(ucwords(str_replace('_',' ',(string)$item['category']))); ?><?php if ($language && $language!=='und'): ?> · <?php echo esc_html(strtoupper($language)); ?><?php endif; ?></p>
    <h1><?php echo esc_html((string)$item['title']); ?></h1>
    <?php if ($recall): ?><div class="mkt-alert mkt-alert-error" role="alert"><h2><?php esc_html_e('Recall / takedown notice','marketplace'); ?></h2><p><?php echo esc_html((string)$recall['reason']); ?><?php if (!empty($recall['batch_ref'])): ?> — <?php echo esc_html(sprintf(__('Batch/reference: %s','marketplace'),(string)$recall['batch_ref'])); ?><?php endif; ?></p><?php if (!empty($recall['regulator_reference'])): ?><p><?php echo esc_html(sprintf(__('Regulatory reference: %s','marketplace'),(string)$recall['regulator_reference'])); ?></p><?php endif; ?><p><?php esc_html_e('Offers and seller-contact actions are disabled while this safety notice is active.','marketplace'); ?></p></div><?php endif; ?>
    <p class="mkt-price mkt-price-large"><bdi><?php echo esc_html((string)$item['currency'].' '.(string)$item['price']); ?></bdi></p>
