    <?php if ($evidence): ?><section class="mkt-safety-note" aria-labelledby="mkt-evidence-public"><h2 id="mkt-evidence-public"><?php esc_html_e('Reviewed product evidence','marketplace'); ?></h2><dl class="mkt-facts"><?php if ($evidence['ingredients']): ?><div><dt><?php esc_html_e('Ingredients / constituents','marketplace'); ?></dt><dd><?php echo esc_html(implode(', ',(array)$evidence['ingredients'])); ?></dd></div><?php endif; ?><div><dt><?php esc_html_e('Manufacturer','marketplace'); ?></dt><dd><?php echo esc_html((string)$evidence['manufacturer']); ?></dd></div><?php foreach (['license_or_registration'=>__('License / registration','marketplace'),'batch_number'=>__('Batch','marketplace'),'expiry_date'=>__('Expiry','marketplace')] as $key=>$label): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html((string)($evidence[$key] ?: ($evidence['not_applicable'][$key] ?? __('Not applicable','marketplace')))); ?></dd></div><?php endforeach; ?></dl><?php if (!empty($evidence['source_refs'])): ?><p><strong><?php esc_html_e('Evidence references:','marketplace'); ?></strong> <?php echo esc_html(implode(' · ',(array)$evidence['source_refs'])); ?></p><?php endif; ?><p><?php esc_html_e('Evidence review does not constitute a cure guarantee or platform endorsement of a treatment outcome.','marketplace'); ?></p></section><?php endif; ?>
    <div class="mkt-actions"><?php if (!$recall && is_user_logged_in()): ?><button class="mkt-button mkt-button-primary" type="button" data-mkt-chat>◉ <?php esc_html_e('Message seller','marketplace'); ?></button><button class="mkt-button mkt-button-secondary" type="button" data-mkt-offer>¤ <?php esc_html_e('Make an offer','marketplace'); ?></button><button class="mkt-button mkt-button-quiet" type="button" data-mkt-save>♡ <?php esc_html_e('Save','marketplace'); ?></button><?php elseif (!$recall): ?><a class="mkt-button mkt-button-primary" href="<?php echo esc_url(wp_login_url($item['url'])); ?>"><?php esc_html_e('Sign in to contact seller','marketplace'); ?></a><?php endif; ?><?php if (is_user_logged_in()): ?><button class="mkt-button mkt-button-quiet" type="button" data-mkt-report>⚑ <?php esc_html_e('Report','marketplace'); ?></button><?php endif; ?><button class="mkt-button mkt-button-quiet" type="button" data-mkt-share data-share-url="<?php echo esc_url($item['url']); ?>">⇧ <?php esc_html_e('Share','marketplace'); ?></button></div>
    <aside class="mkt-safety-note"><h2><?php esc_html_e('Transaction safety','marketplace'); ?></h2><p><?php esc_html_e('Marketplace records offers and deal status but does not guarantee payment, delivery, authenticity or medical outcomes. Verify the seller and product before paying. Do not share patient records.','marketplace'); ?></p></aside>
  </div>
</article>
